syntax = "proto3";

service RobotControl {
  // 클라이언트가 명령을 계속 보내는 스트리밍 RPC
  rpc SendCommand (stream CommandRequest) returns (CommandAck);
}

message CommandRequest {
  double velocity_x = 1;
  double velocity_y = 2;
  int64 timestamp_ms = 3;
}

message CommandAck {
  bool received = 1;
}
